import axios from 'axios';

const API_KEYS = {
  newsapi: process.env.REACT_APP_NEWSAPI_KEY,
  nytimes: process.env.REACT_APP_NYTIMES_KEY,
  guardian: process.env.REACT_APP_GUARDIAN_KEY,
};

const fetchNews = async (query: string, source: string, date: string, category: string, author: string) => {
  let url = '';

  switch (source) {
    case 'newsapi':
      url = `https://newsapi.org/v2/everything?q=${query}&from=${date}&category=${category}&author=${author}&apiKey=${API_KEYS.newsapi}`;
      break;
    case 'nytimes':
      url = `https://api.nytimes.com/svc/search/v2/articlesearch.json?q=${query}&fq=pub_date:(${date}) AND news_desk:(${category}) AND byline:(${author})&api-key=${API_KEYS.nytimes}`;
      break;
    case 'guardian':
      url = `https://content.guardianapis.com/search?q=${query}&from-date=${date}&section=${category}&show-fields=headline,byline,body,publishedDate&api-key=${API_KEYS.guardian}`;
      break;
  }

  const response = await axios.get(url);
  return normalizeResponse(response.data, source);
};

// ✅ Normalize API responses into a common format
const normalizeResponse = (data: any, source: string) => {
  switch (source) {
    case 'newsapi':
      return data.articles.map((article: any) => ({
        title: article.title,
        description: article.description || 'No description available.',
        url: article.url,
        author: article.author || 'Unknown',
        publishedAt: article.publishedAt,
      }));

    case 'nytimes':
      return data.response.docs.map((article: any) => ({
        title: article.headline?.main || 'No title',
        description: article.abstract || 'No description available.',
        url: article.web_url,
        author: article.byline?.original || 'Unknown',
        publishedAt: article.pub_date || '',
      }));

    case 'guardian':
      return data.response.results.map((article: any) => ({
        title: article.fields?.headline || 'No title',
        description: article.fields?.body?.substring(0, 200) + '...' || 'No description available.',
        url: article.webUrl,
        author: article.fields?.byline || 'Unknown',
        publishedAt: article.fields?.publishedDate || '',
      }));

    default:
      return [];
  }
};

export { fetchNews };
